async function loadKokoro(){if(kokoro&&kokoroWorkerReady)return kokoro;if(kokoroLoading)return kokoroLoading;kokoroLoading=(async()=>{let device=state.settings.device;if(device==='auto')device=navigator.gpu?'webgpu':'wasm';let dtype;if(device==='webgpu')dtype=state.settings.memorySaver?'q4f16':(state.settings.dtype==='q4'?'q4f16':state.settings.dtype);else dtype=state.settings.memorySaver?'q4':state.settings.dtype;const cfg=`${device}:${dtype}`;if(kokoroWorkerReady&&kokoroWorkerConfigKey===cfg)return kokoro;setVoiceBusy(true,`Starting voice engine · ${device} ${dtype}`);const r=await kokoroWorkerCall('load',{model:KOKORO_MODEL,device,dtype});kokoroWorkerReady=true;kokoroWorkerConfigKey=`${r.device||device}:${r.dtype||dtype}`;kokoro={generate:async(text,opts={})=>{const g=await kokoroWorkerCall('generate',{text,voice:opts.voice,speed:opts.speed||1});return {toBlob:async()=>g.blob}},dispose:async()=>{try{await kokoroWorkerCall('dispose')}catch{}}};setVoiceBusy(false);setEngineProgress(`Voice engine ready · ${r.device||device} ${r.dtype||dtype}`,false);return kokoro;})();try{return await kokoroLoading}catch(e){console.error(e);stopKokoroWorker('Voice engine failed · '+(e?.message||e));throw e}finally{kokoroLoading=null}}
async function disposeKokoro(){stopKokoroWorker('Voice engine unloaded');}
function applyDictionary(text){let out=text;for(const d of state.dictionary){if(!d.from||!d.to)continue;out=out.replace(new RegExp(`\\b${escapeRe(d.from)}\\b`,'gi'),d.to)}return out;}
function effective(c){const e=EMOTIONS[c.emotion]||EMOTIONS.neutral;return{...c,speed:clamp(c.speed*e.speed,.5,1.6),pitch:clamp(c.pitch+e.pitch,-6,6),tone:c.tone==='neutral'?e.tone:c.tone,pause:Math.max(c.pause,e.pause),intensity:clamp(c.intensity*e.intensity,.5,1.35)}}
async function synthesizeProfile(text,c){text=applyDictionary(text);const p=effective(c);if(c.mode==='clone'&&c.cloneReady)return renderClone(text,p);if(c.mode==='blend')return renderBlend(text,p);return renderKokoro(text,p.voice,p);}
async function renderKokoro(text,voice,p){const t=await loadKokoro();const pitchFactor=Math.pow(2,(p.pitch||0)/12),compSpeed=clamp((p.speed||1)/pitchFactor,.5,1.6);const a=await t.generate(text,{voice,speed:compSpeed});let b=await a.toBlob();return processBlob(b,p);}
async function renderBlend(text,p){setStatus('Rendering blend layer A…');const base={...p,pitch:0,tone:'neutral',intensity:1};const a=await renderKokoro(text,p.blendA,{...base,voice:p.blendA});await sleep(25);setStatus('Rendering blend layer B…');const b=await renderKokoro(text,p.blendB,{...base,voice:p.blendB});const mixed=await mixBlobs(a,b,p.blendWeight);return processBlob(mixed,p);}
async function loadCloneEngine(){if(cloneTTS)return cloneTTS;if(cloneLoading)return cloneLoading;cloneLoading=(async()=>{if(/iPhone|iPad|iPod/i.test(navigator.userAgent))throw new Error('Voice cloning is disabled on iPhone/iPad in this build because the clone model is too large for reliable mobile Safari use. Preset/designed/blended Kokoro voices still work.');if(!navigator.gpu&&!confirm('No WebGPU detected. Voice cloning may be extremely slow or run out of memory using WASM. Try anyway?'))throw new Error('Clone engine canceled because WebGPU is unavailable.');setStatus('Loading clone engine…');let last;for(const url of ['https://esm.sh/voxshot?bundle&deps=@huggingface/transformers','https://esm.sh/voxshot?deps=@huggingface/transformers']){try{const mod=await import(url);const ChatterboxTTS=mod.ChatterboxTTS||mod.default?.ChatterboxTTS;if(!ChatterboxTTS)throw new Error('ChatterboxTTS export not found.');const cb=new ChatterboxTTS({device:navigator.gpu?'webgpu':'wasm'});if(!cb.initialize)throw new Error('Chatterbox initialize() not found.');await cb.initialize();cloneTTS={cb,mod};return cloneTTS}catch(e){last=e}}throw last})();try{return await cloneLoading}finally{cloneLoading=null}}
async function cloneFromFile(c,file){if(!file)throw new Error('Choose a reference recording first.');if(file.size>15*1024*1024)throw new Error('Keep the clone sample under 15 MB.');const {cb}=await loadCloneEngine();const bytes=new Uint8Array(await file.arrayBuffer());setStatus(`Creating ${c.name} clone…`);const id=`${slug(c.name)}-${Date.now()}`;await cb.createVoiceClone(id,bytes);c.cloneId=id;c.cloneReady=true;c.cloneFileName=file.name;save();setStatus('Clone ready')}
async function renderClone(text,p){const {cb}=await loadCloneEngine();if(!p.cloneId)throw new Error('No clone ID for this character.');const opts={voiceId:p.cloneId,temperature:.45,exaggeration:clamp(p.expressiveness||.5,0,1.5),cfgWeight:.5};const out=await cb.generate(text,opts);let blob;if(out instanceof Blob)blob=out;else if(out?.blob instanceof Blob)blob=out.blob;else if(out instanceof ArrayBuffer)blob=new Blob([out],{type:'audio/wav'});else if(ArrayBuffer.isView(out))blob=new Blob([out.buffer],{type:'audio/wav'});else throw new Error('Clone engine returned an unfamiliar audio format.');return processBlob(blob,p)}
async function decode(blob){const C=window.AudioContext||window.webkitAudioContext,ctx=new C();try{return await ctx.decodeAudioData(await blob.arrayBuffer())}finally{await ctx.close()}}
function getMono(a){const n=a.length,out=new Float32Array(n);for(let c=0;c<a.numberOfChannels;c++){const d=a.getChannelData(c);for(let i=0;i<n;i++)out[i]+=d[i]/a.numberOfChannels}return out}
function resample(input,newLen){newLen=Math.max(1,Math.round(newLen));const o=new Float32Array(newLen);if(!input.length)return o;for(let i=0;i<newLen;i++){const x=i*(input.length-1)/Math.max(1,newLen-1),j=Math.floor(x),f=x-j;o[i]=input[j]*(1-f)+input[Math.min(j+1,input.length-1)]*f}return o}
