function tonePcm(pcm,rate,tone,intensity=1){const out=new Float32Array(pcm.length),alphaLow=Math.exp(-2*Math.PI*500/Math.max(1,rate)),alphaHigh=Math.exp(-2*Math.PI*2600/Math.max(1,rate));let low=0,sm=0;for(let i=0;i<pcm.length;i++){const x=pcm[i];low=(1-alphaLow)*x+alphaLow*low;sm=(1-alphaHigh)*x+alphaHigh*sm;const high=x-sm;let y=x;switch(tone){case'warm':y=x*.8+low*.32;break;case'dark':y=x*.66+low*.48;break;case'bright':y=x+high*.28;break;case'crisp':y=x+high*.42;break;case'soft':y=x*.82+low*.22;break;case'hollow':y=x*.72-low*.34;break;case'radio':y=(x-low)*.85-high*.15;break}out[i]=Math.tanh(y*intensity)}return out}
