async function processBlob(blob,p){const a=await decode(blob),rate=a.sampleRate;let pcm=getMono(a);const pf=Math.pow(2,(p.pitch||0)/12);if(Math.abs(p.pitch||0)>.02)pcm=resample(pcm,Math.round(pcm.length/pf));pcm=tonePcm(pcm,rate,p.tone,p.intensity);if(state.settings.normalize)pcm=normalizePcm(pcm,.94);pcm=fadeEdges(pcm,rate,state.settings.fadeMs);return encodeWav(pcm,rate)}
function encodeWav(samples,rate){const ab=new ArrayBuffer(44+samples.length*2),v=new DataView(ab);let o=0;const s=x=>{for(let i=0;i<x.length;i++)v.setUint8(o++,x.charCodeAt(i))};s('RIFF');v.setUint32(o,36+samples.length*2,true);o+=4;s('WAVEfmt ');v.setUint32(o,16,true);o+=4;v.setUint16(o,1,true);o+=2;v.setUint16(o,1,true);o+=2;v.setUint32(o,rate,true);o+=4;v.setUint32(o,rate*2,true);o+=4;v.setUint16(o,2,true);o+=2;v.setUint16(o,16,true);o+=2;s('data');v.setUint32(o,samples.length*2,true);o+=4;for(let i=0;i<samples.length;i++,o+=2){const x=Math.max(-1,Math.min(1,samples[i]));v.setInt16(o,x<0?x*32768:x*32767,true)}return new Blob([ab],{type:'audio/wav'})}
