let previewAudioContext=null,previewBufferSource=null,previewUnlockPromise=null;
function unlockPreviewAudio(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return Promise.resolve(false);try{if(!previewAudioContext)previewAudioContext=new AC();previewUnlockPromise=previewAudioContext.state==='suspended'?previewAudioContext.resume().catch(()=>false):Promise.resolve(true);const b=previewAudioContext.createBuffer(1,1,previewAudioContext.sampleRate||24000),s=previewAudioContext.createBufferSource();s.buffer=b;s.connect(previewAudioContext.destination);s.start(0);return previewUnlockPromise}catch(e){console.warn('Audio unlock failed',e);return Promise.resolve(false)}}
function showPreviewDock(blob,label='Voice preview'){const dock=byId('previewDock'),audio=byId('previewDockAudio'),title=byId('previewDockTitle'),st=byId('previewDockStatus');if(!dock||!audio)return null;const u=URL.createObjectURL(blob);objectUrls.push(u);title.textContent=label;st.textContent='Preview ready. If Safari blocks automatic sound, tap Play below.';audio.src=u;audio.load();dock.classList.add('show');return{audio,url:u,status:st}}
async function playBlob(blob,label='Voice preview'){const dock=showPreviewDock(blob,label);try{await(previewUnlockPromise||Promise.resolve());const AC=window.AudioContext||window.webkitAudioContext;if(!previewAudioContext&&AC)previewAudioContext=new AC();if(previewAudioContext){if(previewAudioContext.state==='suspended')await previewAudioContext.resume();const arr=await blob.arrayBuffer(),buf=await previewAudioContext.decodeAudioData(arr.slice(0));try{previewBufferSource?.stop()}catch{}const src=previewAudioContext.createBufferSource();src.buffer=buf;src.connect(previewAudioContext.destination);previewBufferSource=src;src.onended=()=>{if(dock?.status)dock.status.textContent='Preview finished. Tap Play to hear it again.'};src.start(0);if(dock?.status)dock.status.textContent='Playing preview…';return true}}catch(e){console.warn('Web Audio autoplay path failed',e)}if(dock?.audio){try{await dock.audio.play();dock.status.textContent='Playing preview…';return true}catch(e){dock.status.textContent='Safari blocked automatic playback. Tap Play below.';console.warn('HTML audio autoplay blocked',e)}}return false}
async function previewCharacter(id){if(voicePreviewBusy)return;unlockPreviewAudio();const c=state.characters.find(x=>x.id===id);if(!c)return;const sample=previewText(c.name).slice(0,state.settings.memorySaver?72:140);setVoiceBusy(true,`Preparing ${c.name} preview…`);try{const b=await synthesizeProfile(sample,c);await playBlob(b,`${c.name} voice preview`);setEngineProgress(`${c.name} preview ready`,false)}catch(e){alert(`Preview failed: ${e.message}`);setEngineProgress('Preview failed',false)}finally{setVoiceBusy(false)}}
async function previewLine(id){if(voicePreviewBusy)return;unlockPreviewAudio();const l=chapter().lines.find(x=>x.id===id);if(!l)return;const short={...l,text:l.text.slice(0,state.settings.memorySaver?80:160)};setVoiceBusy(true,`Preparing line preview · ${l.speaker}…`);try{const b=await renderLine(short);await playBlob(b,`${l.speaker} · line preview`);setEngineProgress('Line preview ready',false)}catch(e){alert(`Preview failed: ${e.message}`);setEngineProgress('Preview failed',false)}finally{setVoiceBusy(false)}}
async function renderLine(l){const c=clone(charByName(l.speaker));if(l.delivery&&EMOTIONS[l.delivery])c.emotion=l.delivery;if(l.speed)c.speed=l.speed;return synthesizeProfile(l.text,c)}
async function renderAndStore(id,refresh=false){const l=chapter().lines.find(x=>x.id===id);if(!l)return;setStatus(`Rendering ${l.speaker}…`);try{const b=await renderLine(l);await dbPut(lineKey(l),b);l.generated=true;chapter().masterReady=false;await dbDel(masterKey()).catch(()=>{});save();if(refresh)render();else updateStats();return b}catch(e){l.generated=false;save();throw e}}
async function produceChapter(){if(!chapter().lines.length)throw alert('Map your production/manuscript first.');queueAbort=false;await loadKokoro();const lines=chapter().lines;for(let i=0;i<lines.length;i++){if(queueAbort){setStatus('Stopped');break}const l=lines[i],has=await dbGet(lineKey(l));if(!has)await renderAndStore(l.id,false);progress(i+1,lines.length,`Rendering · ${l.speaker}`);if(state.settings.memorySaver){await sleep(80);if(i%8===7&&navigator.storage?.estimate){const s=await navigator.storage.estimate();console.log('storage',s)}}}if(!queueAbort){progress(lines.length,lines.length,'Assembling master…');await assemble();render();setStatus('Chapter master ready')}}
async function assemble(){const ch=chapter(),parts=[];let rate=24000,total=0;for(const l of ch.lines){const b=await dbGet(lineKey(l));if(!b)continue;const a=await decode(b);rate=a.sampleRate;const pcm=getMono(a),pause=Math.round(rate*Number(l.pause??charByName(l.speaker).pause??.3));parts.push(pcm,new Float32Array(pause));total+=pcm.length+pause}if(!parts.length)throw new Error('No rendered lines to assemble.');const out=new Float32Array(total);let o=0;for(const p of parts){out.set(p,o);o+=p.length}const blob=encodeWav(normalizePcm(out,.94),rate);await dbPut(masterKey(),blob);ch.masterReady=true;save();return blob}
async function restoreMaster(){const b=await dbGet(masterKey());if(!b)return;const u=URL.createObjectURL(b);objectUrls.push(u);byId('masterHolder').innerHTML=`<div class="master"><strong>Chapter Master</strong><audio controls src="${u}"></audio><div class="toolbar"><button id="shareMaster" class="btn good">Save / Share WAV</button></div></div>`;byId('shareMaster').onclick=()=>shareBlob(b,`${slug(state.title)}-${slug(chapter().title)}-master.wav`)}
async function clearChapterAudio(){if(!confirm('Clear all rendered line WAVs and the chapter master from this browser?'))return;for(const l of chapter().lines){await dbDel(lineKey(l)).catch(()=>{});l.generated=false}await dbDel(masterKey()).catch(()=>{});chapter().masterReady=false;save();render()}
async function shareBlob(blob,name){const f=new File([blob],name,{type:blob.type||'audio/wav'});if(navigator.canShare?.({files:[f]})){try{await navigator.share({files:[f],title:name});return}catch(e){if(e.name==='AbortError')return}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),20000)}

function openVoiceLab(id){selectedCharacterId=id;const c=state.characters.find(x=>x.id===id)||state.characters[0];const m=byId('voiceModal');m.classList.remove('hidden');m.innerHTML=`<div class="modalCard"><div class="sectionHead"><div><h2>Voice Lab · ${esc(c.name)}</h2><div class="mini">Build a reusable character voice. Preview uses the same settings as chapter rendering.</div></div><button id="closeVoice" class="btn">Close</button></div><div class="tabs">${['preset','describe','blend','clone'].map(x=>`<button class="tab modeTab ${c.mode===x?'active':''}" data-mode="${x}">${x==='describe'?'Describe':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div id="modeBody"></div><hr style="border:0;border-top:1px solid var(--line);margin:12px 0"><div class="voiceGrid"><div class="field"><label>Speed</label><input id="vSpeed" type="number" min=".5" max="1.6" step=".01" value="${c.speed}"></div><div class="field"><label>Pitch · semitones</label><input id="vPitch" type="number" min="-6" max="6" step=".1" value="${c.pitch}"></div><div class="field"><label>Tone</label><select id="vTone">${TONES.map(x=>`<option ${c.tone===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Emotion</label><select id="vEmotion">${Object.keys(EMOTIONS).map(x=>`<option ${c.emotion===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Intensity</label><input id="vIntensity" type="number" min=".5" max="1.35" step=".01" value="${c.intensity}"></div><div class="field"><label>Pause after line</label><input id="vPause" type="number" min="0" max="3" step=".05" value="${c.pause}"></div></div><div class="field"><label>Preview text</label><textarea id="previewText" rows="3">${esc(previewText(c.name))}</textarea></div><div class="toolbar"><button id="saveVoice" class="btn primary">Save Voice Profile</button><button id="previewVoice" class="btn good">Preview Exact Voice</button></div><div id="voicePreview" class="preview"></div></div>`;renderMode(c);byId('closeVoice').onclick=()=>m.classList.add('hidden');document.querySelectorAll('.modeTab').forEach(t=>t.onclick=()=>{saveVoiceBase(c,false);c.mode=t.dataset.mode;save();openVoiceLab(c.id)});byId('saveVoice').onclick=()=>{saveVoiceBase(c,true);render()};byId('previewVoice').onclick=async()=>{if(voicePreviewBusy)return;unlockPreviewAudio();saveVoiceBase(c,false);const txt=byId('previewText').value.slice(0,state.settings.memorySaver?80:160);setVoiceBusy(true,`Preparing exact ${c.name} preview…`);try{const b=await synthesizeProfile(txt,c);const u=URL.createObjectURL(b);objectUrls.push(u);byId('voicePreview').innerHTML=`<audio controls src="${u}"></audio><div class="mini">Exact rendered WAV. Use this player if Safari blocks automatic playback.</div>`;await playBlob(b,`${c.name} exact voice`);setEngineProgress(`${c.name} exact preview ready`,false)}catch(e){alert(`Preview failed: ${e.message}`);setEngineProgress('Preview failed',false)}finally{setVoiceBusy(false)}};}
function renderMode(c){const el=byId('modeBody');if(c.mode==='preset'){el.innerHTML=`<div class="field"><label>Kokoro voice</label><select id="vVoice">${VOICES.map(v=>`<option value="${v[0]}" ${c.voice===v[0]?'selected':''}>${esc(v[1])}</option>`).join('')}</select></div>`}else if(c.mode==='describe'){el.innerHTML=`<div class="infoBox">Describe the sound you want. The phone turns that into a deterministic voice recipe using Kokoro + pitch/tone/pacing, so the same description stays reproducible.</div><div class="field"><label>Voice description</label><textarea id="vDesc" rows="3" placeholder="deep, weathered, intelligent, quiet, threatening…">${esc(c.description)}</textarea></div><div class="descriptorChips">${['deep','gravelly','old','young','warm','cold','menacing','scholarly','calm','commanding'].map(x=>`<button class="btn tiny addDesc" data-v="${x}">${x}</button>`).join('')}</div><div class="toolbar"><button id="designVoice" class="btn primary">Generate Recipe From Description</button></div><div id="designSummary" class="infoBox">${esc(profileSummary(c))}</div>`;document.querySelectorAll('.addDesc').forEach(b=>b.onclick=()=>{const t=byId('vDesc');t.value=(t.value?`${t.value}, `:'')+b.dataset.v});byId('designVoice').onclick=()=>{designFromDescription(c,byId('vDesc').value);save();openVoiceLab(c.id)}}else if(c.mode==='blend'){el.innerHTML=`<div class="infoBox">Phone-safe Layer Blend: both voices render the same line, then Ashen Voice aligns and mixes the WAVs. It creates a reusable hybrid texture, but it is not Kokoro embedding interpolation.</div><div class="blendGrid"><select id="blendA">${VOICES.map(v=>`<option value="${v[0]}" ${c.blendA===v[0]?'selected':''}>${esc(v[1])}</option>`).join('')}</select><input id="blendW" type="number" min="0" max="1" step=".05" value="${c.blendWeight}"><select id="blendB">${VOICES.map(v=>`<option value="${v[0]}" ${c.blendB===v[0]?'selected':''}>${esc(v[1])}</option>`).join('')}</select><div class="mini">A weight (0–1)</div></div>`}else{el.innerHTML=`<div class="infoBox dangerBox"><b>Real zero-shot clone.</b> Uses a separate Chatterbox/VoxShot model only when you request it. On iPhone this is heavy. Use a clean 5–15 second sample with one speaker and no music. Only clone voices you have permission to use.</div><label class="cloneConsent card"><input id="cloneConsent" type="checkbox"><span class="mini">I have the speaker's permission to create and use this voice clone.</span></label><div class="field"><label>Reference recording</label><input id="cloneFile" type="file" accept="audio/*,.wav,.mp3,.m4a"></div><div class="field"><label>Expressiveness</label><input id="vExpr" type="number" min="0" max="1.5" step=".05" value="${c.expressiveness}"></div><div class="toolbar"><button id="makeClone" class="btn warn">Create / Replace Clone</button></div><div class="mini">${c.cloneReady?`Saved clone: ${esc(c.cloneId)} · source ${esc(c.cloneFileName)}`:'No clone saved for this character yet.'}</div>`;byId('makeClone').onclick=async()=>{if(!byId('cloneConsent').checked)return alert('Confirm that you have permission to clone this speaker.');const f=byId('cloneFile').files?.[0];try{saveVoiceBase(c,false);await cloneFromFile(c,f);openVoiceLab(c.id)}catch(e){alert(`Clone failed: ${e.message}`)}}}}
function saveVoiceBase(c,rerender=false){c.speed=clamp(byId('vSpeed')?.value??c.speed,.5,1.6);c.pitch=clamp(byId('vPitch')?.value??c.pitch,-6,6);c.tone=byId('vTone')?.value||c.tone;c.emotion=byId('vEmotion')?.value||c.emotion;c.intensity=clamp(byId('vIntensity')?.value??c.intensity,.5,1.35);c.pause=Math.max(0,Number(byId('vPause')?.value??c.pause));if(c.mode==='preset')c.voice=byId('vVoice')?.value||c.voice;if(c.mode==='describe')c.description=byId('vDesc')?.value||c.description;if(c.mode==='blend'){c.blendA=byId('blendA')?.value||c.blendA;c.blendB=byId('blendB')?.value||c.blendB;c.blendWeight=clamp(byId('blendW')?.value??c.blendWeight,0,1)}if(c.mode==='clone')c.expressiveness=clamp(byId('vExpr')?.value??c.expressiveness,0,1.5);save();if(rerender){invalidateSpeaker(c.name);byId('voiceModal')?.classList.add('hidden')}}
function designFromDescription(c,desc){c.description=desc;const low=desc.toLowerCase();let recipe={voice:c.voice,speed:c.speed,pitch:c.pitch,tone:c.tone};let hits=0;for(const [key,r] of Object.entries(DESC_LIBRARY)){if(low.includes(key)){recipe={...recipe,...r};hits++}}if(/female|woman|girl/.test(low)&&!hits)recipe.voice='af_heart';if(/male|man|boy/.test(low)&&!hits)recipe.voice='am_michael';if(/whisper/.test(low)){recipe.tone='soft';recipe.speed=.88;c.emotion='whispered'}if(/evil|ominous|sinister/.test(low)){recipe.tone='dark';recipe.pitch=-1.5;recipe.speed=.86;c.emotion='ominous'}c.voice=recipe.voice;c.speed=recipe.speed;c.pitch=recipe.pitch;c.tone=recipe.tone;c.mode='describe';}
function previewText(name){if(name==='Narrator')return 'The desert spat secrets when it felt like it. Today it gave up a ridge of brick half-buried in sand.';return `${name}. The room was sealed for a reason. Whatever you do, do not open the second door.`;}
function editLine(id,patch,invalidate){const l=chapter().lines.find(x=>x.id===id);Object.assign(l,patch);if(invalidate){l.generated=false;chapter().masterReady=false;dbDel(lineKey(l)).catch(()=>{});dbDel(masterKey()).catch(()=>{})}save();}
function invalidateSpeaker(name){for(const l of chapter().lines)if(l.speaker===name){l.generated=false;dbDel(lineKey(l)).catch(()=>{})}chapter().masterReady=false;dbDel(masterKey()).catch(()=>{});save();}
function updateWord(id,k,v){const d=state.dictionary.find(x=>x.id===id);if(d)d[k]=v;save();}
function addCharacter(){const n=prompt('Character name?');if(!n?.trim())return;const c=makeChar({name:n.trim()});state.characters.push(c);selectedCharacterId=c.id;save();render();openVoiceLab(c.id)}
function backup(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});shareBlob(b,`${slug(state.title)}-ashen-voice-v070.json`)}
async function restore(e){const f=e.target.files?.[0];if(!f)return;try{state=migrate(JSON.parse(await f.text()));save();render()}catch(err){alert(`Restore failed: ${err.message}`)}}
function revokeAll(){revokeUrls();}
window.addEventListener('pagehide',()=>{try{if(state)save();}catch{}try{previewBufferSource?.stop()}catch{}try{previewAudioContext?.close()}catch{}revokeAll()});
function boot(){try{state=loadState();selectedCharacterId=state.characters[0]?.id||null;render();document.body.dataset.ashenReady='1';setStatus('Ready');}catch(e){console.error(e);(window.__ashenFatal||alert)((e&&e.stack)||String(e));}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
